/* put this in SP later, but for now, just use sql in ssis
BEGIN
    AGP.PR_BIDR_REFRESH_FACET;
END;
*/
BEGIN

/*TRUNCATE TABLE AGP.BIDR_XFER_LINE --does not work, so just use delete*/
DELETE FROM AGP.BIDR_XFER_LINE;
COMMIT;

/*delete any duplicate root claims just in case*/
DELETE FROM AGP.BIDR_STG_CLAIM C
WHERE C.ROWID >
  ANY 
    (SELECT C2.ROWID
    FROM AGP.BIDR_STG_CLAIM C2
    WHERE C2.CLCL_ID = C.CLCL_ID);
COMMIT;

/* all claims (including adjustments) must be captured so..
for every root claim, generate 00,01,..97,98,99 then use the generated claims that only truly exists in facets 
ex:  claim 1122334455   will generate to   112233445501,112233445502,112233445503,.....112233445598,112233445599 
(if its a true facet claim)
claim 5566778899 will generate to 556677889901,556677889902,556677889903,.....556677889998,556677889999 (if its a true facet claim)
*/
INSERT INTO AGP.BIDR_STG_CLAIM (CLCL_ID, ROOT_CLCL_ID, CCERT_LEAD_TYPE, SC_SCHEME, SC_SUBSCHEME, MARKET, ITERATION, CM_TD_NOTIFY_FLG)
WITH TT (ROOT_CLCL_ID, GEN_CLCL_ID) AS (SELECT C.ROOT_CLCL_ID, C.ROOT_CLCL_ID || A.SUFFIX AS GEN_CLCL_ID /*add the generated suffix 00,01,02..98,99*/
FROM AGP.BIDR_STG_CLAIM C  
INNER JOIN (SELECT LPAD(LTRIM(ROWNUM - 1), 2, '0') AS SUFFIX /*generate suffix from 00 to 99*/
FROM DUAL CONNECT BY ROWNUM <= 101) A ON 1=1) /*use 101 and deduct 1 so 00 can be generated in the beginning and end in 99*/    
/*WHERE C.CLCL_ID IN ('123191103000','12318I707400') */
SELECT /*+ parallel(C2,4) parallel(C3,4)*/ 
TT.GEN_CLCL_ID,  SUBSTR(TT.GEN_CLCL_ID, 1 ,10), C2.CCERT_LEAD_TYPE, C2.SC_SCHEME, C2.SC_SUBSCHEME, C2.MARKET, C2.ITERATION, C2.CM_TD_NOTIFY_FLG 
FROM TT 
INNER JOIN AGP.BIDR_STG_CLAIM C2 ON C2.ROOT_CLCL_ID = TT.ROOT_CLCL_ID
INNER JOIN FACETS.CMC_CLCL_CLAIM C3 ON C3.CLCL_ID = TT.GEN_CLCL_ID; /*insert the ones that are truly existing in facets*/
COMMIT;

/*delete any duplicates just in case*/
DELETE FROM AGP.BIDR_STG_CLAIM C
WHERE C.ROWID >
  ANY 
    (SELECT C2.ROWID
    FROM AGP.BIDR_STG_CLAIM C2
    WHERE C2.CLCL_ID = C.CLCL_ID);
COMMIT;

/*delete any root claims just in case because all claim data will be fetch based on real CLCL_ID from here on*/
DELETE FROM AGP.BIDR_STG_CLAIM C
WHERE C.CLCL_ID IS NULL;
COMMIT;

END;

