UPDATE AGP.BIDR_XFER_LINE SET
LINE_DATA = REPLACE(LINE_DATA, '|', '#PIPE#'); /*second replace the pipe-data to something distinct; this will get replaced with real pipe later in mssql */
COMMIT;

UPDATE AGP.BIDR_XFER_LINE SET
LINE_DATA = REPLACE(LINE_DATA, '#TEMPPIPE#', '|'); /*third replace the pipe-separator with a real separator */
COMMIT;


END;

